WITH remaining_keys AS (SELECT id, status FROM accounts EXCEPT ALL SELECT id, status FROM accounts WHERE customer_id IN (3, 21, 37)), kept_rows AS (SELECT s.* FROM accounts s INNER JOIN remaining_keys k ON s.id = k.id AND s.status = k.status) SELECT s.id, s.customer_id, s.account_type, s.status, (SELECT MIN(x.amount) FROM orders x WHERE x.customer_id = s.customer_id) AS min_order_amount FROM kept_rows s;
